def S(kind, objective, speech, arg=0, need=1, loc=1, seconds=0):
    return dict(kind=kind, objective=objective, speech=speech, arg=arg, need=need, loc=loc, seconds=seconds)
def M(name, sender, role, stages, gear=0):
    missions.append(dict(name=name, sender=sender, role=role, stages=stages, gear=gear))
def H(obj, speech, **kw): return S('HAIL', obj, speech, **kw)
def D(obj='Return to the commissioning station with your report.', speech="That's the last piece we needed. Come home and we'll settle up.", **kw): return S('DOCK', obj, speech, loc=0, **kw)
def K(obj='Defeat the attackers. Protect the civilian ships.', speech="They're coming round again! Keep them away from us.", **kw): return S('COMBAT', obj, speech, **kw)
def P(obj, speech, **kw): return S('RECOVER', obj, speech, **kw)
def E(obj, speech, **kw): return S('ESCORT', obj, speech, need=kw.pop('need',3), seconds=90, **kw)
def T(obj, speech, **kw): return S('SITE', obj, speech, **kw)
