# These replace the terse shared fallbacks above with a distinct final call from
# each mission contact. Keeping the overrides beside the authored catalogue makes
# it difficult for new missions to inherit generic dialogue unnoticed.
AUTHORED_COMBAT_CALLS = {
    'Convoy Escort': "Contacts closing fast! Break their attack before they reach my convoy.",
    'Rescue Under Fire': "Hostiles are sweeping the wreck. Hold them off while I keep the survivor's beacon locked.",
    'The Last Container': "They're back for the cargo. Clear them out and I'll guide you to our canister.",
    'Recovery Crew Protection': "Raiders inbound across our work lights! Give my recovery crews room to operate.",
}
AUTHORED_RETURN_CALLS = {
    'Convoy Escort': "Every surviving ship is accounted for. Bring your flight record in, Commander; the crews want to thank you.",
    'Freighter Departure Guard': "The freighter has made the jump point intact. Port Control has your payment ready.",
    'Relief Ship Rendezvous': "The relief ship is safely through. Return to Control; those supplies will reach people who need them.",
    'Recovery Crew Protection': "Crew and cargo are both secure. Come in from the dark and we'll divide the salvage properly.",
    'Wanted, Identity Unknown': "Positive identification, clean arrest record. Report to the precinct and collect the warrant payment.",
    "The Courier's Witness": "Ash Kite is finished and the witness is safe. Bring me your combat log so I can close the case.",
    'Police Checkpoint Patrol': "Checkpoint net is quiet again. Return to Patrol Control for debrief and payment.",
    'Pirate Supply Chain': "Supplier neutralised. Bring the final evidence home; this network is closed for good.",
    'The Wrong Accusation': "Your decision is on record. Meet me at the review desk and we'll file the truth, not the rumour.",
    'Botanical Collection': "The biology team is already arguing over your scans. Bring the field record in before they name anything after you.",
    'Wildlife Field Study': "Excellent restraint out there. Return with the recordings; behaviour this natural is rare data.",
    'Silent Observatory': "We have the missing sky survey. Come back to the observatory desk and see what it was tracking.",
    'Drone Recovery Expedition': "Both records arrived intact. Bring the drone report in; I owe you an explanation and a repair bill.",
    'Outpost Communications Failure': "The whole relay chain is green again. Return to the outpost desk and we'll sign off your service fee.",
    'Lost Settler Archive': "Their voices are safe in the archive now. Come home and help me enter their names into the record.",
    'Skyport Service Circuit': "Weather, cooling and shuttle beacon all nominal. Dock at Control for your engineer's receipt.",
    'Listening-Post Trail': "The final contact checks out. Bring me your receiver log; I want to know who buried that signal.",
    'Anomaly Comparison': "The readings agree, and they should not. Return with the raw data before the echoes change again.",
    "Salvager's Treasure Map": "Ada's old clue led somewhere after all. Bring the cache in and we'll open it under witness.",
}

for mission in missions:
    for stage in mission['stages']:
        if stage['speech'] == "They're coming round again! Keep them away from us.":
            stage['speech'] = AUTHORED_COMBAT_CALLS[mission['name']]
        elif stage['speech'] == "That's the last piece we needed. Come home and we'll settle up.":
            stage['speech'] = AUTHORED_RETURN_CALLS[mission['name']]

assert len(missions)==40
assert all(s['speech'] not in {
    "They're coming round again! Keep them away from us.",
    "That's the last piece we needed. Come home and we'll settle up.",
} for m in missions for s in m['stages'])
out=['/* Authored by tools/mission-expansion-catalog.py. */', '#define EXPEDITION_COUNT 40', '#define EXPEDITION_STAGES 8', 'static const ExpeditionDef expedition_defs[EXPEDITION_COUNT]={']
for m in missions:
    out.append(' {%s,%s,%s,%d,%d,{' % (json.dumps(m['name']),json.dumps(m['sender']),m['role'],m['gear'],len(m['stages'])))
    for s in m['stages']:
        out.append('  {XP_%s,%d,%d,%d,%d,%s,%s},' % (s['kind'],s['arg'],s['need'],s['loc'],s['seconds'],json.dumps(s['objective']),json.dumps(s['speech'])))
    out.append(' }},')
out.append('};')
(ROOT/'src/mission-expansion-catalog.h').write_text('\n'.join(out)+'\n',encoding='utf-8')
doc=['# Staged mission catalogue', '', 'Forty authored contracts; each line below is a successive objective.', '']
for i,m in enumerate(missions,1):
    doc+=['## %d. %s'%(i,m['name']), '', '**Contact:** '+m['sender'], '']
    doc += ['%d. %s'%(j+1,s['objective']) for j,s in enumerate(m['stages'])]
    doc+=['']
(ROOT/'docs/MISSION-STAGES-388.md').write_text('\n'.join(doc),encoding='utf-8')
print('Generated',len(missions),'contracts,',sum(len(m['stages']) for m in missions),'stages')
